rtl:
module top (
    input  wire a,
    output wire y
);

    wire n1;
    wire n2;
    wire n3;

    BUF_X1 U1 (.A(a),  .Y(n1));
    BUF_X1 U2 (.A(n1), .Y(n2));
    BUF_X1 U3 (.A(n2), .Y(n3));
    BUF_X1 U4 (.A(n3), .Y(y));

endmodule

lib:
library (demo_lib) {
    delay_model : table_lookup;
    time_unit : "1ns";
    voltage_unit : "1V";
    current_unit : "1mA";
    capacitive_load_unit (1, pf);
    nom_process : 1;
    nom_voltage : 1.0;
    nom_temperature : 25;

    lu_table_template (delay_template) {
        variable_1 : input_net_transition;
        variable_2 : total_output_net_capacitance;
        index_1 ("0.01, 0.10");
        index_2 ("0.01, 0.10");
    }

    cell (BUF_X1) {
        area : 1.0;
        pin (A) {
            direction : input;
            capacitance : 0.01;
        }
        pin (Y) {
            direction : output;
            function : "A";
            timing () {
                related_pin : "A";
                timing_sense : positive_unate;
                cell_rise (delay_template) {
                    values ("0.05, 0.08", "0.07, 0.10");
                }
                cell_fall (delay_template) {
                    values ("0.05, 0.08", "0.07, 0.10");
                }
                rise_transition (delay_template) {
                    values ("0.02, 0.03", "0.03, 0.04");
                }
                fall_transition (delay_template) {
                    values ("0.02, 0.03", "0.03, 0.04");
                }
            }
        }
    }
}
